import javafx.application.*;import javafx.animation.PauseTransition;import javafx.scene.*;import javafx.scene.control.*;import javafx.stage.*;import javafx.util.Duration;import javafx.embed.swing.SwingFXUtils;import javax.imageio.ImageIO;import java.nio.file.*;import com.google.gson.*;
/** Own TextInputDialog using the unchanged source strings; no config, database or OS input. */
public class TableNameDialogOracle {
 public static void main(String[] args){Application.launch(Probe.class,args);}
 public static class Probe extends Application {
 public void start(Stage owner){owner.setScene(new Scene(new javafx.scene.layout.Pane(),896,650));owner.setOpacity(.01);owner.show();var dialog=new TextInputDialog();dialog.initOwner(owner);dialog.setTitle("新建表");dialog.setHeaderText("请输入表名");dialog.setContentText("表名:");dialog.setOnShown(e->{((Stage)dialog.getDialogPane().getScene().getWindow()).setOpacity(.01);var pause=new PauseTransition(Duration.millis(400));pause.setOnFinished(done->{try{var root=dialog.getDialogPane();var json=new JsonObject();json.addProperty("width",root.getWidth());json.addProperty("height",root.getHeight());var controls=new JsonArray();DatabaseObjectAlertsOracle.walk(root,controls);json.add("controls",controls);var output=Path.of(getParameters().getRaw().get(0));Files.writeString(output,new GsonBuilder().setPrettyPrinting().create().toJson(json));ImageIO.write(SwingFXUtils.fromFXImage(root.snapshot(null,null),null),"png",Path.of(output+".png").toFile());((Button)root.lookupButton(ButtonType.CANCEL)).fire();owner.close();Platform.exit();System.exit(0);}catch(Throwable error){error.printStackTrace();System.exit(1);}});pause.play();});dialog.showAndWait();}
}}
